cuda_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

__global__ void layer_norm_kernel(
    const __half* __restrict__ input,
    __half* __restrict__ output,
    const __half* __restrict__ weight,
    const __half* __restrict__ bias,
    int batch_size,
    int features,
    int dim1,
    int dim2,
    float eps
) {
    int batch_idx = blockIdx.x;
    int feature_idx = blockIdx.y;

    if (batch_idx >= batch_size || feature_idx >= features) return;

    // Shared memory for mean and variance calculation
    extern __shared__ float shared_data[];
    float* shared_mean = shared_data;
    float* shared_var = shared_data + blockDim.x;

    int total_elements = dim1 * dim2;
    int tid = threadIdx.x;

    // Load data into shared memory and calculate mean
    float sum = 0.0f;
    for (int i = tid; i < total_elements; i += blockDim.x) {
        int idx = batch_idx * (features * dim1 * dim2) + feature_idx * (dim1 * dim2) + i;
        float val = __half2float(input[idx]);
        sum += val;
    }
    shared_mean[tid] = sum;
    __syncthreads();

    // Reduction to get mean
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            shared_mean[tid] += shared_mean[tid + s];
        }
        __syncthreads();
    }

    float mean = shared_mean[0] / total_elements;

    // Calculate variance
    float sum_sq = 0.0f;
    for (int i = tid; i < total_elements; i += blockDim.x) {
        int idx = batch_idx * (features * dim1 * dim2) + feature_idx * (dim1 * dim2) + i;
        float val = __half2float(input[idx]);
        float diff = val - mean;
        sum_sq += diff * diff;
    }
    shared_var[tid] = sum_sq;
    __syncthreads();

    // Reduction to get variance
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            shared_var[tid] += shared_var[tid + s];
        }
        __syncthreads();
    }

    float var = shared_var[0] / total_elements;
    float inv_std = rsqrtf(var + eps);

    // Normalize and scale
    for (int i = tid; i < total_elements; i += blockDim.x) {
        int idx = batch_idx * (features * dim1 * dim2) + feature_idx * (dim1 * dim2) + i;
        float val = __half2float(input[idx]);
        float normalized = (val - mean) * inv_std;
        float scaled = normalized * __half2float(weight[feature_idx]) + __half2float(bias[feature_idx]);
        output[idx] = __float2half(scaled);
    }
}

torch::Tensor layer_norm_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    float eps
) {
    auto output = torch::empty_like(input);

    auto input_ = input.contiguous();
    auto weight_ = weight.contiguous();
    auto bias_ = bias.contiguous();
    auto output_ = output.contiguous();

    int batch_size = input.size(0);
    int features = input.size(1);
    int dim1 = input.size(2);
    int dim2 = input.size(3);

    dim3 grid_dim(batch_size, features, 1);
    dim3 block_dim(256, 1, 1);

    size_t shared_mem_size = 2 * 256 * sizeof(float);

    layer_norm_kernel<<<grid_dim, block_dim, shared_mem_size>>>(
        input_.data_ptr<at::Half>(),
        output_.data_ptr<at::Half>(),
        weight_.data_ptr<at::Half>(),
        bias_.data_ptr<at::Half>(),
        batch_size,
        features,
        dim1,
        dim2,
        eps
    );

    return output_;
}
"""

